```csharp
using System;
using System.Collections.Generic;

namespace GameOfLife
{
 class Program
 {
 static void Main(string[] args)
 {
 int[,] board = new int[100, 100];
 int lifeCount = 0;

 Console.WriteLine("Начинаем игру! У нас есть 100x100 игрового поля.");
 Console.Write("Введите количество жизней для змейки: ");
 string input = Console.ReadLine();

 for (int i = 0; i < 100; i++)
 {
 for (int j = 0; j < 100; j++)
 {
 if (input == "1") // Змейка живёт
 {
 board[i, j] = 2; // Змейка живёт
 lifeCount++;
 }
 else if (input == "0") // Змейка смерjeta
 {
 board[i, j] = 0; // Змейка смерjeta
 }
 }
 }

 Console.WriteLine($"Сейчас в игре {lifeCount} змейки.");
 }
 }
}
```

Эта программа представляет собой простую игру змейки на шарпах. Змейка может созревать или смереть в зависимости от её состояния.
